-- TYPED_BACKFILL_JOURNAL_V1 durable STRUCTURAL observations only.
-- No implicit installation, operator grants, business effects, runtime/RLS,
-- COMPLETE/COMMITTED, effects verification, reconciliation or retention policy.
-- Root installs atomically in an explicitly owned schema and verifies the catalog.
-- Before every store call the application MUST validate applicability alongside
-- the genuine original compiler-issued plan with typed-journal-contract.ts.
-- SQL checks coherent complete descriptors, but cannot reconstruct the original
-- application plan/ownership/reviewer evidence or prove that initial metadata
-- came from that genuine plan. A checksum authenticates neither caller nor DB.
-- Structural metadata numbers are exact safe integers only. Original numeric,
-- JSON and array wires stay outside this store, bound by their exact checksums.
-- Compiler chunk id and retryIdentity are preserved: no new operation IDs/clocks.
-- Selective root grants only: schema USAGE, exact function EXECUTE,
-- SELECT/INSERT both new controls; UPDATE(plan_digest) plan only for FOR UPDATE
-- (identity trigger rejects changes), UPDATE(state) chunk. No source-table grant.

CREATE FUNCTION nevora_tenancy._typed_journal_canonical_json(v pg_catalog.json)
RETURNS pg_catalog.text LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER
SET search_path = pg_catalog AS $canonical$
DECLARE k pg_catalog.text; result pg_catalog.text; item record; n pg_catalog.text;
BEGIN
 IF v IS NULL THEN RAISE EXCEPTION 'TYPED_JOURNAL_INVALID_JSON'; END IF;
 k := pg_catalog.json_typeof(v);
 IF k = 'null' THEN RETURN 'null'; END IF;
 IF k = 'boolean' THEN RETURN (v::pg_catalog.jsonb)::pg_catalog.text; END IF;
 IF k = 'string' THEN RETURN pg_catalog.to_json(v #>> '{}')::pg_catalog.text; END IF;
 IF k = 'number' THEN
  n := v::pg_catalog.text;
  IF n !~ '^-?(0|[1-9][0-9]*)$' OR n = '-0' OR
     n::pg_catalog.numeric < -9007199254740991 OR n::pg_catalog.numeric > 9007199254740991
  THEN RAISE EXCEPTION 'TYPED_JOURNAL_UNSUPPORTED_METADATA_NUMBER'; END IF;
  RETURN n;
 END IF;
 IF k = 'array' THEN
  result := '';
  FOR item IN SELECT a.value FROM pg_catalog.json_array_elements(v) WITH ORDINALITY AS a(value, ordinal) ORDER BY a.ordinal LOOP
   result := result || CASE WHEN result = '' THEN '' ELSE ',' END || nevora_tenancy._typed_journal_canonical_json(item.value);
  END LOOP;
  RETURN '[' || result || ']';
 END IF;
 IF k = 'object' THEN
  IF (SELECT pg_catalog.count(*) FROM pg_catalog.json_each(v)) <>
     (SELECT pg_catalog.count(DISTINCT e.key COLLATE pg_catalog."C") FROM pg_catalog.json_each(v) AS e)
  THEN RAISE EXCEPTION 'TYPED_JOURNAL_DUPLICATE_JSON_FIELD'; END IF;
  result := '';
  FOR item IN SELECT e.key,e.value FROM pg_catalog.json_each(v) AS e ORDER BY e.key COLLATE pg_catalog."C" LOOP
   result := result || CASE WHEN result = '' THEN '' ELSE ',' END || pg_catalog.to_json(item.key)::pg_catalog.text || ':' || nevora_tenancy._typed_journal_canonical_json(item.value);
  END LOOP;
  RETURN '{' || result || '}';
 END IF;
 RAISE EXCEPTION 'TYPED_JOURNAL_INVALID_JSON';
END $canonical$;

CREATE FUNCTION nevora_tenancy._typed_journal_fields(v pg_catalog.jsonb, names pg_catalog.text[])
RETURNS pg_catalog.bool LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path = pg_catalog
AS $fields$ SELECT pg_catalog.jsonb_typeof(v) = 'object' AND v ?& names AND
 (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v)) = pg_catalog.cardinality(names) $fields$;

CREATE FUNCTION nevora_tenancy._typed_journal_digest(v pg_catalog.jsonb)
RETURNS pg_catalog.text LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path = pg_catalog
AS $digest$ SELECT pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(nevora_tenancy._typed_journal_canonical_json(v::pg_catalog.json),'UTF8')),'hex') $digest$;

CREATE FUNCTION nevora_tenancy._typed_journal_key(v pg_catalog.jsonb, arity pg_catalog.int4)
RETURNS pg_catalog.bool LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path = pg_catalog
AS $key$ SELECT CASE WHEN pg_catalog.jsonb_typeof(v) = 'array' THEN
 pg_catalog.jsonb_array_length(v) = arity AND NOT EXISTS
 (SELECT 1 FROM pg_catalog.jsonb_array_elements(v) AS a WHERE pg_catalog.jsonb_typeof(a.value) NOT IN ('string','number','boolean')) ELSE false END $key$;

CREATE FUNCTION nevora_tenancy._typed_journal_validate_description(canonical pg_catalog.text)
