 IF pg_catalog.jsonb_array_length(d->'tables') <> pg_catalog.jsonb_array_length(tables) THEN RAISE EXCEPTION 'TYPED_JOURNAL_COVERAGE_DRIFT'; END IF;
 FOR t IN SELECT a.value FROM pg_catalog.jsonb_array_elements(d->'tables') AS a LOOP
  expected := tables->table_ordinal;
  IF nevora_tenancy._typed_journal_fields(t,ARRAY['table','source','storage','anchor','sidecar','originalColumns','primaryKey','mirroredIdentityColumns','globalFences','count','sourceChecksum','wireChecksum','expectedMetadataChecksum']) IS NOT TRUE OR
  (t-ARRAY['count','sourceChecksum','wireChecksum','expectedMetadataChecksum']) IS DISTINCT FROM expected OR
  pg_catalog.jsonb_typeof(t->'count') IS DISTINCT FROM 'number' OR (t->>'count')::pg_catalog.numeric < 0
  THEN RAISE EXCEPTION 'TYPED_JOURNAL_COVERAGE_DRIFT'; END IF;
  FOREACH field IN ARRAY ARRAY['sourceChecksum','wireChecksum','expectedMetadataChecksum'] LOOP
   IF pg_catalog.jsonb_typeof(t->field) IS DISTINCT FROM 'string' OR t->>field !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'TYPED_JOURNAL_TABLE_CHECKSUM_DRIFT'; END IF;
  END LOOP;
  table_ordinal := table_ordinal+1;
 END LOOP;
 FOR c IN SELECT a.value FROM pg_catalog.jsonb_array_elements(d->'chunks') AS a LOOP
  IF nevora_tenancy._typed_journal_fields(c,ARRAY['format','id','retryIdentity','planDigest','table','ordinal','count','firstKey','lastKey','keys','keysChecksum','sourceChecksum','expectedMetadataChecksum','rows','rowsChecksum']) IS NOT TRUE OR
  c->>'format' IS DISTINCT FROM 'TYPED_BACKFILL_JOURNAL_CHUNK_V1' OR c->>'planDigest' IS DISTINCT FROM b->>'planDigest' OR
  c->>'retryIdentity' IS DISTINCT FROM c->>'id' OR pg_catalog.jsonb_typeof(c->'ordinal') IS DISTINCT FROM 'number' OR (c->>'ordinal')::pg_catalog.numeric <> ordinal OR
  pg_catalog.jsonb_typeof(c->'count') IS DISTINCT FROM 'number' OR (c->>'count')::pg_catalog.numeric < 1 OR
  pg_catalog.jsonb_typeof(c->'keys') IS DISTINCT FROM 'array' OR pg_catalog.jsonb_typeof(c->'rows') IS DISTINCT FROM 'array' OR
  (c->>'count')::pg_catalog.numeric <> pg_catalog.jsonb_array_length(c->'keys') OR (c->>'count')::pg_catalog.numeric <> pg_catalog.jsonb_array_length(c->'rows')
  THEN RAISE EXCEPTION 'TYPED_JOURNAL_INVALID_CHUNK'; END IF;
  SELECT a.ordinal::pg_catalog.int4-1 INTO current_table FROM pg_catalog.jsonb_array_elements(tables) WITH ORDINALITY AS a(value,ordinal) WHERE a.value->>'table' = c->>'table';
  IF NOT FOUND OR current_table < previous_table THEN RAISE EXCEPTION 'TYPED_JOURNAL_COVERAGE_DRIFT'; END IF;
  previous_table := current_table; expected := tables->current_table; arity := pg_catalog.jsonb_array_length(expected->'primaryKey');
  IF c->'firstKey' IS DISTINCT FROM c->'keys'->0 OR c->'lastKey' IS DISTINCT FROM c->'keys'->(pg_catalog.jsonb_array_length(c->'keys')-1) THEN RAISE EXCEPTION 'TYPED_JOURNAL_INVALID_KEY'; END IF;
  FOREACH field IN ARRAY ARRAY['id','retryIdentity','planDigest','keysChecksum','sourceChecksum','expectedMetadataChecksum','rowsChecksum'] LOOP
   IF pg_catalog.jsonb_typeof(c->field) IS DISTINCT FROM 'string' OR c->>field !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'TYPED_JOURNAL_INVALID_CHUNK'; END IF;
  END LOOP;
  IF c->>'keysChecksum' IS DISTINCT FROM nevora_tenancy._typed_journal_digest(c->'keys') OR c->>'rowsChecksum' IS DISTINCT FROM nevora_tenancy._typed_journal_digest(c->'rows') THEN RAISE EXCEPTION 'TYPED_JOURNAL_ROW_CHECKSUM_DRIFT'; END IF;
  -- Recompute only the original chunk structural ID descriptor, never full plan.
  checksum := nevora_tenancy._typed_journal_digest(pg_catalog.jsonb_build_object('format','TYPED_TENANT_BACKFILL_CHUNK_V1','planDigest',c->'planDigest','ordinal',c->'ordinal','table',c->'table','count',c->'count','firstKey',c->'firstKey','lastKey',c->'lastKey','keys',c->'keys','sourceChecksum',c->'sourceChecksum','expectedMetadataChecksum',c->'expectedMetadataChecksum'));
  IF c->>'id' IS DISTINCT FROM checksum THEN RAISE EXCEPTION 'TYPED_JOURNAL_CHUNK_IDENTITY_DRIFT'; END IF;
  row_ordinal := 0; chunk_source := '[]'; chunk_effect := '[]';
  FOR row_value IN SELECT a.value FROM pg_catalog.jsonb_array_elements(c->'rows') AS a LOOP
   IF nevora_tenancy._typed_journal_fields(row_value,ARRAY['key','sourceChecksum','wireChecksum','mirroredIdentityChecksum','sourceObservationChecksum','action','expectedMetadataChecksum']) IS NOT TRUE OR
   nevora_tenancy._typed_journal_key(row_value->'key',arity) IS NOT TRUE OR row_value->'key' IS DISTINCT FROM c->'keys'->row_ordinal OR
   pg_catalog.jsonb_typeof(row_value->'action') IS DISTINCT FROM 'string' OR row_value->>'action' NOT IN ('ASSIGN_ADDED_DIRECT_WORKSPACE','INSERT_TYPED_SIDECAR','PRESERVE_EXISTING_NO_WRITE','GLOBAL_NO_WRITE') OR
   (expected->>'storage' = 'GLOBAL_SECURITY_CONTROL' AND row_value->>'action' <> 'GLOBAL_NO_WRITE') OR
   (expected->>'storage' <> 'GLOBAL_SECURITY_CONTROL' AND row_value->>'action' = 'GLOBAL_NO_WRITE') OR
   (expected->>'storage' = 'TYPED_HISTORICAL_SIDECAR' AND row_value->>'action' NOT IN ('INSERT_TYPED_SIDECAR','PRESERVE_EXISTING_NO_WRITE')) OR
   (expected->>'storage' <> 'TYPED_HISTORICAL_SIDECAR' AND row_value->>'action' = 'INSERT_TYPED_SIDECAR')
   THEN RAISE EXCEPTION 'TYPED_JOURNAL_INVALID_ROW'; END IF;
   FOREACH field IN ARRAY ARRAY['sourceChecksum','wireChecksum','mirroredIdentityChecksum','sourceObservationChecksum','expectedMetadataChecksum'] LOOP
    IF pg_catalog.jsonb_typeof(row_value->field) IS DISTINCT FROM 'string' OR row_value->>field !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'TYPED_JOURNAL_ROW_CHECKSUM_DRIFT'; END IF;
   END LOOP;
   all_rows := all_rows || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('table',c->'table','row',row_value));
   chunk_source := chunk_source || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('key',row_value->'key','sourceChecksum',row_value->'sourceChecksum','wireChecksum',row_value->'wireChecksum'));
   chunk_effect := chunk_effect || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('key',row_value->'key','action',row_value->'action','checksum',row_value->'expectedMetadataChecksum'));
   row_ordinal := row_ordinal+1;
  END LOOP;
  IF c->>'sourceChecksum' IS DISTINCT FROM nevora_tenancy._typed_journal_digest(chunk_source) OR c->>'expectedMetadataChecksum' IS DISTINCT FROM nevora_tenancy._typed_journal_digest(chunk_effect) THEN RAISE EXCEPTION 'TYPED_JOURNAL_ROW_CHECKSUM_DRIFT'; END IF;
  ordinal := ordinal+1;
 END LOOP;
 IF (SELECT pg_catalog.count(DISTINCT a.value->>'id' COLLATE pg_catalog."C") FROM pg_catalog.jsonb_array_elements(d->'chunks') AS a) <> ordinal OR
 (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_array_elements(all_rows)) <> (SELECT pg_catalog.count(DISTINCT nevora_tenancy._typed_journal_canonical_json(pg_catalog.jsonb_build_array(a.value->'table',a.value->'row'->'key')::pg_catalog.json) COLLATE pg_catalog."C") FROM pg_catalog.jsonb_array_elements(all_rows) AS a)
 THEN RAISE EXCEPTION 'TYPED_JOURNAL_COVERAGE_DRIFT'; END IF;
 FOR t IN SELECT a.value FROM pg_catalog.jsonb_array_elements(d->'tables') AS a LOOP
  SELECT COALESCE(pg_catalog.jsonb_agg(a.value->'row' ORDER BY a.ordinal),'[]') INTO table_rows FROM pg_catalog.jsonb_array_elements(all_rows) WITH ORDINALITY AS a(value,ordinal) WHERE a.value->>'table' = t->>'table';
  IF (t->>'count')::pg_catalog.numeric <> pg_catalog.jsonb_array_length(table_rows) THEN RAISE EXCEPTION 'TYPED_JOURNAL_COVERAGE_DRIFT'; END IF;
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('key',a.value->'key','checksum',a.value->'sourceChecksum') ORDER BY a.ordinal),'[]') INTO chunk_source FROM pg_catalog.jsonb_array_elements(table_rows) WITH ORDINALITY AS a(value,ordinal);
  IF t->>'sourceChecksum' IS DISTINCT FROM nevora_tenancy._typed_journal_digest(chunk_source) THEN RAISE EXCEPTION 'TYPED_JOURNAL_TABLE_CHECKSUM_DRIFT'; END IF;
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('key',a.value->'key','wireChecksum',a.value->'wireChecksum') ORDER BY a.ordinal),'[]') INTO chunk_source FROM pg_catalog.jsonb_array_elements(table_rows) WITH ORDINALITY AS a(value,ordinal);
  IF t->>'wireChecksum' IS DISTINCT FROM nevora_tenancy._typed_journal_digest(chunk_source) THEN RAISE EXCEPTION 'TYPED_JOURNAL_TABLE_CHECKSUM_DRIFT'; END IF;
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('key',a.value->'key','action',a.value->'action','checksum',a.value->'expectedMetadataChecksum') ORDER BY a.ordinal),'[]') INTO chunk_effect FROM pg_catalog.jsonb_array_elements(table_rows) WITH ORDINALITY AS a(value,ordinal);
  IF t->>'expectedMetadataChecksum' IS DISTINCT FROM nevora_tenancy._typed_journal_digest(chunk_effect) THEN RAISE EXCEPTION 'TYPED_JOURNAL_TABLE_CHECKSUM_DRIFT'; END IF;
 END LOOP;
 RETURN d;
END $description$;

CREATE TABLE nevora_tenancy.typed_backfill_journal_plan (
 plan_digest pg_catalog.text COLLATE pg_catalog."C" PRIMARY KEY CHECK (plan_digest ~ '^[a-f0-9]{64}$'),
 descriptor_canonical pg_catalog.text COLLATE pg_catalog."C" NOT NULL,
 boundary pg_catalog.jsonb NOT NULL,
 chunk_count pg_catalog.int8 NOT NULL CHECK (chunk_count >= 0)
);
CREATE TABLE nevora_tenancy.typed_backfill_journal_chunk (
 plan_digest pg_catalog.text COLLATE pg_catalog."C" NOT NULL REFERENCES nevora_tenancy.typed_backfill_journal_plan(plan_digest),
 chunk_id pg_catalog.text COLLATE pg_catalog."C" NOT NULL CHECK (chunk_id ~ '^[a-f0-9]{64}$'),
 ordinal pg_catalog.int8 NOT NULL CHECK (ordinal >= 0),
 chunk_canonical pg_catalog.text COLLATE pg_catalog."C" NOT NULL,
 retry_identity pg_catalog.text COLLATE pg_catalog."C" NOT NULL UNIQUE CHECK (retry_identity ~ '^[a-f0-9]{64}$'),
 state pg_catalog.text COLLATE pg_catalog."C" NOT NULL DEFAULT 'NOT_STARTED' CHECK (state IN ('NOT_STARTED','STARTED','UNKNOWN')),
 PRIMARY KEY(plan_digest,chunk_id), UNIQUE(plan_digest,ordinal)
);

CREATE FUNCTION nevora_tenancy._typed_journal_plan_identity()
RETURNS pg_catalog.trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog AS $plan_identity$
DECLARE d pg_catalog.jsonb;
BEGIN
 IF TG_OP = 'DELETE' OR (TG_OP = 'UPDATE' AND OLD IS DISTINCT FROM NEW) THEN RAISE EXCEPTION 'TYPED_JOURNAL_IDENTITY_IMMUTABLE'; END IF;
 d := nevora_tenancy._typed_journal_validate_description(NEW.descriptor_canonical);
 IF NEW.plan_digest <> d->'boundary'->>'planDigest' OR NEW.boundary <> d->'boundary' OR NEW.chunk_count <> pg_catalog.jsonb_array_length(d->'chunks')
 THEN RAISE EXCEPTION 'TYPED_JOURNAL_PLAN_IDENTITY_DRIFT'; END IF;
 RETURN NEW;
END $plan_identity$;

CREATE FUNCTION nevora_tenancy._typed_journal_chunk_identity()
RETURNS pg_catalog.trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog AS $chunk_identity$
DECLARE d pg_catalog.jsonb; expected pg_catalog.jsonb;
BEGIN
 IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'TYPED_JOURNAL_IDENTITY_IMMUTABLE'; END IF;
 IF TG_OP = 'UPDATE' THEN
  IF (pg_catalog.to_jsonb(OLD)-'state') IS DISTINCT FROM (pg_catalog.to_jsonb(NEW)-'state') THEN RAISE EXCEPTION 'TYPED_JOURNAL_IDENTITY_IMMUTABLE'; END IF;
  IF NEW.state NOT IN ('NOT_STARTED','STARTED','UNKNOWN') THEN RAISE EXCEPTION 'TYPED_JOURNAL_COMPLETION_BLOCKED'; END IF;
  IF NOT (NEW.state = OLD.state OR (OLD.state = 'NOT_STARTED' AND NEW.state IN ('STARTED','UNKNOWN')) OR (OLD.state = 'STARTED' AND NEW.state = 'UNKNOWN'))
  THEN RAISE EXCEPTION 'TYPED_JOURNAL_UNKNOWN_REQUIRES_RECHECK'; END IF;
 ELSE
  IF NEW.state <> 'NOT_STARTED' THEN RAISE EXCEPTION 'TYPED_JOURNAL_INITIAL_STATE_REQUIRED'; END IF;
 END IF;
 SELECT p.descriptor_canonical::pg_catalog.jsonb INTO d FROM nevora_tenancy.typed_backfill_journal_plan AS p WHERE p.plan_digest = NEW.plan_digest;
 IF d IS NULL THEN RAISE EXCEPTION 'TYPED_JOURNAL_ORIGINAL_PLAN_REQUIRED'; END IF;
 SELECT a.value INTO expected FROM pg_catalog.jsonb_array_elements(d->'chunks') AS a WHERE a.value->>'id' = NEW.chunk_id;
 IF expected IS NULL OR NEW.ordinal <> (expected->>'ordinal')::pg_catalog.int8 OR
    NEW.chunk_canonical <> nevora_tenancy._typed_journal_canonical_json(expected::pg_catalog.json) OR
    NEW.retry_identity <> expected->>'retryIdentity'
 THEN RAISE EXCEPTION 'TYPED_JOURNAL_CHUNK_IDENTITY_DRIFT'; END IF;
 RETURN NEW;
END $chunk_identity$;

CREATE FUNCTION nevora_tenancy._typed_journal_assert_coverage(requested_plan pg_catalog.text)
RETURNS pg_catalog.void LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog AS $coverage$
DECLARE p nevora_tenancy.typed_backfill_journal_plan%ROWTYPE; c record; stored nevora_tenancy.typed_backfill_journal_chunk%ROWTYPE;
BEGIN
 SELECT * INTO p FROM nevora_tenancy.typed_backfill_journal_plan AS j WHERE j.plan_digest = requested_plan FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'TYPED_JOURNAL_ORIGINAL_PLAN_REQUIRED'; END IF;
 IF (SELECT pg_catalog.count(*) FROM nevora_tenancy.typed_backfill_journal_chunk AS j WHERE j.plan_digest = requested_plan) <> p.chunk_count THEN RAISE EXCEPTION 'TYPED_JOURNAL_COVERAGE_DRIFT'; END IF;
 FOR c IN SELECT a.value FROM pg_catalog.jsonb_array_elements(p.descriptor_canonical::pg_catalog.jsonb->'chunks') AS a LOOP
  SELECT * INTO stored FROM nevora_tenancy.typed_backfill_journal_chunk AS j WHERE j.plan_digest = requested_plan AND j.chunk_id = c.value->>'id';
  IF NOT FOUND OR stored.ordinal <> (c.value->>'ordinal')::pg_catalog.int8 OR
     stored.chunk_canonical <> nevora_tenancy._typed_journal_canonical_json(c.value::pg_catalog.json) OR
     stored.retry_identity <> c.value->>'retryIdentity' OR stored.state NOT IN ('NOT_STARTED','STARTED','UNKNOWN')
  THEN RAISE EXCEPTION 'TYPED_JOURNAL_COVERAGE_DRIFT'; END IF;
 END LOOP;
END $coverage$;

CREATE FUNCTION nevora_tenancy._typed_journal_coverage_trigger()
RETURNS pg_catalog.trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog AS $coverage_trigger$
BEGIN
 PERFORM nevora_tenancy._typed_journal_assert_coverage(CASE WHEN TG_OP = 'DELETE' THEN OLD.plan_digest ELSE NEW.plan_digest END);
 RETURN NULL;
END $coverage_trigger$;
CREATE FUNCTION nevora_tenancy._typed_journal_no_truncate()
RETURNS pg_catalog.trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog AS $no_truncate$
BEGIN RAISE EXCEPTION 'TYPED_JOURNAL_IDENTITY_IMMUTABLE'; END $no_truncate$;
CREATE TRIGGER typed_journal_plan_identity BEFORE INSERT OR UPDATE OR DELETE ON nevora_tenancy.typed_backfill_journal_plan FOR EACH ROW EXECUTE FUNCTION nevora_tenancy._typed_journal_plan_identity();
CREATE TRIGGER typed_journal_chunk_identity BEFORE INSERT OR UPDATE OR DELETE ON nevora_tenancy.typed_backfill_journal_chunk FOR EACH ROW EXECUTE FUNCTION nevora_tenancy._typed_journal_chunk_identity();
CREATE CONSTRAINT TRIGGER typed_journal_plan_coverage AFTER INSERT OR UPDATE OR DELETE ON nevora_tenancy.typed_backfill_journal_plan DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION nevora_tenancy._typed_journal_coverage_trigger();
CREATE CONSTRAINT TRIGGER typed_journal_chunk_coverage AFTER INSERT OR UPDATE OR DELETE ON nevora_tenancy.typed_backfill_journal_chunk DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION nevora_tenancy._typed_journal_coverage_trigger();
CREATE TRIGGER typed_journal_plan_no_truncate BEFORE TRUNCATE ON nevora_tenancy.typed_backfill_journal_plan FOR EACH STATEMENT EXECUTE FUNCTION nevora_tenancy._typed_journal_no_truncate();
CREATE TRIGGER typed_journal_chunk_no_truncate BEFORE TRUNCATE ON nevora_tenancy.typed_backfill_journal_chunk FOR EACH STATEMENT EXECUTE FUNCTION nevora_tenancy._typed_journal_no_truncate();

CREATE FUNCTION nevora_tenancy.read_typed_backfill_journal(requested_description pg_catalog.text)
RETURNS pg_catalog.jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog AS $read$
DECLARE d pg_catalog.jsonb; p nevora_tenancy.typed_backfill_journal_plan%ROWTYPE; rows pg_catalog.jsonb;
BEGIN
 d := nevora_tenancy._typed_journal_validate_description(requested_description);
 SELECT * INTO p FROM nevora_tenancy.typed_backfill_journal_plan AS j WHERE j.plan_digest = d->'boundary'->>'planDigest' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'TYPED_JOURNAL_ORIGINAL_PLAN_REQUIRED'; END IF;
 IF p.descriptor_canonical <> requested_description COLLATE pg_catalog."C" THEN RAISE EXCEPTION 'TYPED_JOURNAL_CHANGED_ORIGINAL_RETRY'; END IF;
 PERFORM nevora_tenancy._typed_journal_assert_coverage(p.plan_digest);
 SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('chunk',j.chunk_canonical::pg_catalog.jsonb,'state',j.state,'retryIdentity',j.retry_identity) ORDER BY j.ordinal) INTO rows
 FROM nevora_tenancy.typed_backfill_journal_chunk AS j WHERE j.plan_digest = p.plan_digest;
 RETURN pg_catalog.jsonb_build_object('format','TYPED_BACKFILL_JOURNAL_OBSERVATION_V1','boundary',p.boundary,'descriptorChecksum',p.descriptor_canonical::pg_catalog.jsonb->'descriptorChecksum','rows',COALESCE(rows,'[]'::pg_catalog.jsonb),'effectsVerified',false,'reconciliation',NULL);
END $read$;

CREATE FUNCTION nevora_tenancy.register_typed_backfill_journal(requested_description pg_catalog.text)
RETURNS pg_catalog.jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog AS $register$
DECLARE d pg_catalog.jsonb; p nevora_tenancy.typed_backfill_journal_plan%ROWTYPE; c record; inserted pg_catalog.int8;
BEGIN
 d := nevora_tenancy._typed_journal_validate_description(requested_description);
 INSERT INTO nevora_tenancy.typed_backfill_journal_plan(plan_digest,descriptor_canonical,boundary,chunk_count)
 VALUES(d->'boundary'->>'planDigest',requested_description,d->'boundary',pg_catalog.jsonb_array_length(d->'chunks')) ON CONFLICT(plan_digest) DO NOTHING;
 GET DIAGNOSTICS inserted = ROW_COUNT;
 SELECT * INTO p FROM nevora_tenancy.typed_backfill_journal_plan AS j WHERE j.plan_digest = d->'boundary'->>'planDigest' FOR UPDATE;
 IF p.descriptor_canonical <> requested_description COLLATE pg_catalog."C" THEN RAISE EXCEPTION 'TYPED_JOURNAL_CHANGED_ORIGINAL_RETRY'; END IF;
 IF inserted = 1 THEN
  FOR c IN SELECT a.value FROM pg_catalog.jsonb_array_elements(d->'chunks') AS a LOOP
   INSERT INTO nevora_tenancy.typed_backfill_journal_chunk(plan_digest,chunk_id,ordinal,chunk_canonical,retry_identity,state)
   VALUES(p.plan_digest,c.value->>'id',(c.value->>'ordinal')::pg_catalog.int8,nevora_tenancy._typed_journal_canonical_json(c.value::pg_catalog.json),c.value->>'retryIdentity','NOT_STARTED');
  END LOOP;
 END IF;
 PERFORM nevora_tenancy._typed_journal_assert_coverage(p.plan_digest);
 RETURN nevora_tenancy.read_typed_backfill_journal(requested_description);
END $register$;

CREATE FUNCTION nevora_tenancy.observe_typed_backfill_journal(requested_description pg_catalog.text, requested_chunk pg_catalog.text, requested_retry pg_catalog.text, requested_state pg_catalog.text)
RETURNS pg_catalog.jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog AS $observe$
DECLARE d pg_catalog.jsonb; p nevora_tenancy.typed_backfill_journal_plan%ROWTYPE; c nevora_tenancy.typed_backfill_journal_chunk%ROWTYPE;
BEGIN
 IF requested_state IS NULL OR requested_state NOT IN ('NOT_STARTED','STARTED','UNKNOWN') THEN RAISE EXCEPTION 'TYPED_JOURNAL_COMPLETION_BLOCKED'; END IF;
 d := nevora_tenancy._typed_journal_validate_description(requested_description);
 SELECT * INTO p FROM nevora_tenancy.typed_backfill_journal_plan AS j WHERE j.plan_digest = d->'boundary'->>'planDigest' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'TYPED_JOURNAL_ORIGINAL_PLAN_REQUIRED'; END IF;
 IF p.descriptor_canonical <> requested_description COLLATE pg_catalog."C" THEN RAISE EXCEPTION 'TYPED_JOURNAL_CHANGED_ORIGINAL_RETRY'; END IF;
 PERFORM nevora_tenancy._typed_journal_assert_coverage(p.plan_digest);
 SELECT * INTO c FROM nevora_tenancy.typed_backfill_journal_chunk AS j WHERE j.plan_digest = p.plan_digest AND j.chunk_id = requested_chunk FOR UPDATE;
 IF NOT FOUND OR requested_retry IS NULL OR requested_retry <> c.retry_identity THEN RAISE EXCEPTION 'TYPED_JOURNAL_RETRY_DRIFT'; END IF;
 UPDATE nevora_tenancy.typed_backfill_journal_chunk AS j SET state = requested_state WHERE j.plan_digest = p.plan_digest AND j.chunk_id = c.chunk_id;
 RETURN nevora_tenancy.read_typed_backfill_journal(requested_description);
END $observe$;

REVOKE ALL ON TABLE nevora_tenancy.typed_backfill_journal_plan,nevora_tenancy.typed_backfill_journal_chunk FROM PUBLIC;
REVOKE ALL ON FUNCTION nevora_tenancy._typed_journal_canonical_json(pg_catalog.json),nevora_tenancy._typed_journal_fields(pg_catalog.jsonb,pg_catalog.text[]),nevora_tenancy._typed_journal_digest(pg_catalog.jsonb),nevora_tenancy._typed_journal_key(pg_catalog.jsonb,pg_catalog.int4),nevora_tenancy._typed_journal_validate_description(pg_catalog.text),nevora_tenancy._typed_journal_plan_identity(),nevora_tenancy._typed_journal_chunk_identity(),nevora_tenancy._typed_journal_assert_coverage(pg_catalog.text),nevora_tenancy._typed_journal_coverage_trigger(),nevora_tenancy._typed_journal_no_truncate(),nevora_tenancy.read_typed_backfill_journal(pg_catalog.text),nevora_tenancy.register_typed_backfill_journal(pg_catalog.text),nevora_tenancy.observe_typed_backfill_journal(pg_catalog.text,pg_catalog.text,pg_catalog.text,pg_catalog.text) FROM PUBLIC;
